    const el = leaf.view.containerEl.querySelector(".tl-canvas");
    let f = el[Object.keys(el).find((k) => k.startsWith("__reactFiber"))];
    while (f) { const v = f.memoizedProps?.value; if (v?.store && v.getCurrentPageShapes) { const stale = window.__dgEd === v; window.__dgEd = v; return { newEditor: !stale }; } f = f.return; }
    return { newEditor: false, notFound: true };`);
