      await sleep(1500);
    },
  },
  {
    name: "C Escape twice still deletes pending arrow",
    input: "Evidence→Claim, menu open, Escape, Escape",
    expected: "menu gone, no arrows in store; saved file has no pending arrow",
    run: async (ctx) => {
